using System;using System.IO;using System.Text;using System.Linq;using Frociart;
internal static class ReferenceSourceTests {
 static int checks;static void Check(bool b,string s){checks++;if(!b)throw new Exception(s);}
 static int Main(string[] args){try{string root=args[0];foreach(string language in new[]{"python","java"}){string folder=Path.Combine(root,language+"-pc");Directory.CreateDirectory(folder);foreach(var line in File.ReadAllLines(Path.Combine(root,"cases.tsv"))){string name=line.Split('\t')[0];var d=DiagramIO.Load(Path.Combine(root,"pc-"+name+".frociart"));var before=DiagramIO.EncodeDocument(d);var ir=FlowSource.Compile(d);Check(ir.CanGenerate,name+" valid IR");var code=language=="python"?FlowPython.Generate(ir):FlowJava.Generate(ir);Check(code.Text==(language=="python"?FlowPython.Generate(ir):FlowJava.Generate(ir)).Text,name+" deterministic");Check(before.SequenceEqual(DiagramIO.EncodeDocument(d)),name+" source does not mutate document");foreach(var scope in ir.Scopes)foreach(var block in scope.Blocks)Check(code.ForBlock(scope.Id,block.Id).Count>0,name+" source mapping");File.WriteAllText(Path.Combine(folder,name+(language=="python"?".py":".java")),code.Text,new UTF8Encoding(false));Console.WriteLine("PASS "+language+" "+name);}}Console.WriteLine("REFERENCE_SOURCE_PC PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
